def group_current_adventure_routes(apps, schema_editor):
    """Give each adventure one group while retaining its recording references."""
    alias = schema_editor.connection.alias
    Adventure = apps.get_model('adventures', 'AdventurePage')
    Link = apps.get_model('adventures', 'AdventureRoute')
    Route = apps.get_model('adventures', 'Route')
    Revision = apps.get_model('wagtailcore', 'Revision')
    ContentType = apps.get_model('contenttypes', 'ContentType')
    content_type = ContentType.objects.using(alias).filter(
        app_label='adventures', model='adventurepage'
    ).first()

    for page in Adventure.objects.using(alias).all().iterator():
        links = list(
            Link.objects.using(alias)
            .filter(page_id=page.pk)
            .order_by('sort_order', 'pk')
        )
        if not links:
            continue

        route_ids = list(dict.fromkeys(link.route_id for link in links))
        routes = {
            route.pk: route
            for route in Route.objects.using(alias).filter(pk__in=route_ids)
        }
        group = Route.objects.using(alias).create(
            name=page.title[:255], kind='group', activity_type='', file=''
        )
        for position, route_id in enumerate(route_ids):
            route = routes[route_id]
            if route.parent_route_id is not None:
                # A recording can belong to one group. Copy its database row for
                # another adventure, pointing at the same existing media files.
                route.pk = None
                route.parent_route_id = None
                route.is_public = False
                route.save(using=alias)
            route.parent_route_id = group.pk
            route.position = position
            route.save(using=alias, update_fields=['parent_route', 'position'])

        Link.objects.using(alias).filter(page_id=page.pk).delete()
        group_link = Link.objects.using(alias).create(
            page_id=page.pk, route_id=group.pk, sort_order=0
        )

        if content_type:
            for revision in Revision.objects.using(alias).filter(
                content_type_id=content_type.pk, object_id=str(page.pk)
            ).iterator():
                content = revision.content
                revision_ids = [
                    link.get('route')
                    for link in content.get('adventure_routes', [])
                ]
                if revision_ids != route_ids:
                    continue
                content['adventure_routes'] = [
                    {
                        'pk': group_link.pk,
                        'page': page.pk,
                        'route': group.pk,
                        'sort_order': 0,
                    }
                ]
                Revision.objects.using(alias).filter(pk=revision.pk).update(
                    content=content
                )


